window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["resend"]={html:"<div class=\"own-resend\">\n  <header class=\"rs-nav\" id=\"rsTop\">\n    <a class=\"rs-brand\" href=\"#rs-top\" aria-label=\"Northwind home\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 6.5 12 13l9-6.5M4 5h16a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n      <span>Northwind</span>\n    </a>\n    <nav class=\"rs-menu\" aria-label=\"Primary\">\n      <a href=\"#rs-features\">Features</a>\n      <a href=\"#rs-integrate\">Integrate</a>\n      <a href=\"#rs-pricing\">Pricing</a>\n      <a href=\"#rs-customers\">Customers</a>\n    </nav>\n    <div class=\"rs-nav-right\">\n      <a class=\"rs-link\" href=\"#\">Sign in</a>\n      <a class=\"rs-btn rs-btn-primary\" href=\"#rs-pricing\">Get started</a>\n      <button class=\"rs-burger\" type=\"button\" aria-label=\"Menu\" data-rs-burger><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"rs-top\">\n    <section class=\"rs-hero\" aria-labelledby=\"rs-h1\">\n      <div class=\"rs-glow rs-glow-orange\" aria-hidden=\"true\"></div>\n      <div class=\"rs-hero-inner\">\n        <span class=\"rs-badge\">Now in general availability</span>\n        <h1 id=\"rs-h1\" class=\"rs-h1\">Operations,<br>reimagined</h1>\n        <p class=\"rs-hero-sub\">A single place for throughput, yield, and cost &#8212; built for the teams that keep the floor moving.</p>\n        <div class=\"rs-hero-cta\">\n          <a class=\"rs-btn rs-btn-primary rs-btn-lg\" href=\"#rs-pricing\">Start for free</a>\n          <a class=\"rs-btn rs-btn-outline rs-btn-lg\" href=\"#rs-integrate\">Read the docs</a>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rs-features\" class=\"rs-section\" aria-labelledby=\"rs-features-h\">\n      <div class=\"rs-glow rs-glow-blue rs-glow-top\" aria-hidden=\"true\"></div>\n      <div class=\"rs-sec-inner\">\n        <h2 id=\"rs-features-h\" class=\"rs-h2\">Everything in your context</h2>\n        <p class=\"rs-sec-sub\">Three primitives, one operating picture. Every board, metric, and alert shares the same model.</p>\n        <div class=\"rs-grid\">\n          <article class=\"rs-card rs-card-bordered\">\n            <span class=\"rs-card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 18V9m5 9V5m5 13v-7m5 7V7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></span>\n            <h3 class=\"rs-h3\">Metrics you can trust</h3>\n            <p class=\"rs-card-copy\">Define a metric once. Northwind reconciles every definition and shows its lineage.</p>\n          </article>\n          <article class=\"rs-card rs-card-bordered\">\n            <span class=\"rs-card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M4 12h16M12 4c2.5 3 2.5 13 0 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg></span>\n            <h3 class=\"rs-h3\">Every region live</h3>\n            <p class=\"rs-card-copy\">Plants, ports, and hubs stream in as they report. No batch window, no overnight lag.</p>\n          </article>\n          <article class=\"rs-card rs-card-bordered\">\n            <span class=\"rs-card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3l8 4v6c0 5-3.5 7.5-8 8-4.5-.5-8-3-8-8V7z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/><path d=\"m8.5 12 2.5 2.5L16 10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></span>\n            <h3 class=\"rs-h3\">Alerts with evidence</h3>\n            <p class=\"rs-card-copy\">Anomaly detection flags drift and attaches the exact comparison behind the call.</p>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rs-integrate\" class=\"rs-section rs-section-tight\" aria-labelledby=\"rs-integrate-h\">\n      <div class=\"rs-glow rs-glow-green rs-glow-top\" aria-hidden=\"true\"></div>\n      <div class=\"rs-sec-inner rs-split\">\n        <div class=\"rs-split-copy\">\n          <p class=\"rs-eyebrow\">Integrate this weekend</p>\n          <h2 id=\"rs-integrate-h\" class=\"rs-h2 rs-h2-tight\">First-class developer experience</h2>\n          <p class=\"rs-sec-sub\">One SDK, every source. Query a board, stream updates, or wire an alert into your own pipeline.</p>\n          <ul class=\"rs-bullets\">\n            <li>Typed SDKs for Python and TypeScript</li>\n            <li>Webhooks on any metric threshold</li>\n            <li>Full API to every board and alert</li>\n          </ul>\n        </div>\n        <div class=\"rs-code\" role=\"img\" aria-label=\"Northwind SDK example\">\n          <div class=\"rs-code-top\">\n            <span class=\"rs-lights\" aria-hidden=\"true\"><i class=\"rs-l-red\"></i><i class=\"rs-l-yellow\"></i><i class=\"rs-l-green\"></i></span>\n            <span class=\"rs-code-name\">pipeline.py</span>\n          </div>\n          <div class=\"rs-code-tabs\">\n            <span class=\"rs-tab on\">Python</span>\n            <span class=\"rs-tab\">TypeScript</span>\n            <span class=\"rs-tab\">cURL</span>\n          </div>\n          <pre class=\"rs-code-body\"><code><span class=\"rs-c-kw\">from</span> northwind <span class=\"rs-c-kw\">import</span> Client\n\nclient = Client()\nboard = client.boards.<span class=\"rs-c-fn\">get</span>(<span class=\"rs-c-str\">\"regional-throughput\"</span>)\n<span class=\"rs-c-kw\">for</span> point <span class=\"rs-c-kw\">in</span> board.<span class=\"rs-c-fn\">stream</span>():\n    <span class=\"rs-c-fn\">print</span>(point.region, point.yield_pct)\n<span class=\"rs-c-com\"># luzon 94.6  busan 98.1  sydney 91.3</span></code></pre>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"rs-email\" aria-labelledby=\"rs-email-h\">\n      <div class=\"rs-sec-inner\">\n        <h2 id=\"rs-email-h\" class=\"rs-h2 rs-center\">Beyond the dashboard</h2>\n        <p class=\"rs-sec-sub rs-center\">Schedule a summary and Northwind renders it as a clean brief, ready for the morning review.</p>\n        <div class=\"rs-mail\">\n          <div class=\"rs-mail-head\">\n            <span class=\"rs-mail-dot\" aria-hidden=\"true\"></span>\n            <div>\n              <p class=\"rs-mail-sub\">Daily operations brief</p>\n              <p class=\"rs-mail-to\">to ops-leads@northwind.example</p>\n            </div>\n          </div>\n          <div class=\"rs-mail-body\">\n            <p class=\"rs-mail-hi\">Good morning &#8212; here is yesterday at a glance.</p>\n            <div class=\"rs-mail-stats\">\n              <div><b>94.6%</b><span>Avg yield</span></div>\n              <div><b>98.1%</b><span>On-time</span></div>\n              <div><b>$12.4M</b><span>Throughput</span></div>\n            </div>\n            <p class=\"rs-mail-note\">Two lines flagged for drift in Luzon &#183; one alert in Busan cleared.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rs-pricing\" class=\"rs-section\" aria-labelledby=\"rs-pricing-h\">\n      <div class=\"rs-sec-inner\">\n        <h2 id=\"rs-pricing-h\" class=\"rs-h2\">Pricing</h2>\n        <p class=\"rs-sec-sub\">Start free, upgrade when the floor depends on it.</p>\n        <div class=\"rs-price-grid\">\n          <article class=\"rs-tier\">\n            <h3 class=\"rs-tier-name\">Hobby</h3>\n            <p class=\"rs-tier-price\">$0</p>\n            <p class=\"rs-tier-desc\">For one analyst exploring the numbers.</p>\n            <ul class=\"rs-checks\">\n              <li>3 boards</li>\n              <li>1 source</li>\n              <li>Community support</li>\n            </ul>\n            <a class=\"rs-btn rs-btn-outline rs-btn-block\" href=\"#\">Start free</a>\n          </article>\n          <article class=\"rs-tier rs-tier-featured\">\n            <h3 class=\"rs-tier-name\">Scale</h3>\n            <p class=\"rs-tier-price\">$40<span>/mo</span></p>\n            <p class=\"rs-tier-desc\">For teams running the daily review.</p>\n            <ul class=\"rs-checks\">\n              <li>Unlimited boards</li>\n              <li>10 sources</li>\n              <li>Alerting &amp; webhooks</li>\n            </ul>\n            <a class=\"rs-btn rs-btn-primary rs-btn-block\" href=\"#\">Choose Scale</a>\n          </article>\n          <article class=\"rs-tier\">\n            <h3 class=\"rs-tier-name\">Enterprise</h3>\n            <p class=\"rs-tier-price\">Custom</p>\n            <p class=\"rs-tier-desc\">For the org on one source of truth.</p>\n            <ul class=\"rs-checks\">\n              <li>SSO &amp; audit</li>\n              <li>Unlimited sources</li>\n              <li>Dedicated support</li>\n            </ul>\n            <a class=\"rs-btn rs-btn-ghost rs-btn-block\" href=\"#\">Contact us</a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rs-customers\" class=\"rs-section rs-section-tight\" aria-labelledby=\"rs-customers-h\">\n      <div class=\"rs-glow rs-glow-red rs-glow-top\" aria-hidden=\"true\"></div>\n      <div class=\"rs-sec-inner\">\n        <h2 id=\"rs-customers-h\" class=\"rs-h2 rs-center\">Trusted on the floor</h2>\n        <blockquote class=\"rs-quote\">\n          <p>&ldquo;One number the whole shift trusts. That changed how we run the review.&rdquo;</p>\n          <footer class=\"rs-quote-by\">\n            <span class=\"rs-avatar\" aria-hidden=\"true\">MR</span>\n            <span><b>Mara Reyes</b><em>Operations Lead, fictional manufacturer</em></span>\n          </footer>\n        </blockquote>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"rs-foot\">\n    <div class=\"rs-foot-inner\">\n      <div class=\"rs-foot-brand\">\n        <span>Northwind</span>\n        <p class=\"rs-foot-status\"><i aria-hidden=\"true\"></i>All systems operational</p>\n      </div>\n      <div class=\"rs-foot-cols\">\n        <h3>Product</h3><a href=\"#\">Features</a><a href=\"#\">Pricing</a><a href=\"#\">Docs</a><a href=\"#\">Changelog</a>\n      </div>\n      <div class=\"rs-foot-cols\">\n        <h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Customers</a><a href=\"#\">Careers</a><a href=\"#\">Blog</a>\n      </div>\n      <div class=\"rs-foot-cols\">\n        <h3>Legal</h3><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a><a href=\"#\">Status</a>\n      </div>\n    </div>\n    <div class=\"rs-foot-bottom\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <span>Sample data &#8212; showcase only</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Resend design language, for showcase.html ══════════\n   True-black canvas, off-white text, serif-led display headlines, translucent\n   hairline borders instead of shadows, rounded-12 containers, soft atmospheric\n   accent glows, and a single white CTA pill as the brightest pixel. */\n\n.own-resend {\n  --primary: #fcfdff;\n  --primary-on: #000000;\n  --ink: #fcfdff;\n  --body: rgba(252, 253, 255, .86);\n  --charcoal: rgba(252, 253, 255, .7);\n  --mute: #a1a4a5;\n  --ash: #888e90;\n  --stone: #464a4d;\n  --on-light: #000000;\n  --on-light-mute: rgba(0, 0, 51, .7);\n  --canvas: #000000;\n  --surface-card: #0a0a0c;\n  --surface-elevated: #101012;\n  --surface-deep: #06060a;\n  --hairline: rgba(255, 255, 255, .06);\n  --hairline-strong: rgba(255, 255, 255, .14);\n  --divider-soft: rgba(255, 255, 255, .04);\n  --accent-orange: #ff801f;\n  --accent-orange-glow: rgba(255, 89, 0, .22);\n  --accent-yellow: #ffc53d;\n  --accent-blue: #3b9eff;\n  --accent-blue-glow: rgba(0, 117, 255, .34);\n  --accent-green: #11ff99;\n  --accent-green-glow: rgba(34, 255, 153, .18);\n  --accent-red: #ff2047;\n  --accent-red-glow: rgba(255, 32, 71, .34);\n  --link: #3b9eff;\n\n  --r-xs: 4px;\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-full: 9999px;\n\n  --serif: 'Domaine Display', 'Sohne', 'Tiempos Headline', Georgia, 'Times New Roman', serif;\n  --ui: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;\n  --sans: 'ABC Favorit', 'Geist', 'Inter Tight', system-ui, sans-serif;\n  --mono: 'Geist Mono', 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: 96px;\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--body);\n  font-family: var(--ui);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-resend *, .own-resend *::before, .own-resend *::after { box-sizing: border-box; }\n.own-resend a { color: inherit; text-decoration: none; }\n.own-resend button { font: inherit; cursor: pointer; }\n.own-resend :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: var(--r-sm); }\n.own-resend .rs-center { text-align: center; margin-left: auto; margin-right: auto; }\n\n/* ── nav ──────────────────────────────────────────────────────────────────── */\n.own-resend .rs-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 22px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(0, 0, 0, .8); backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--hairline);\n}\n.own-resend .rs-brand { display: inline-flex; align-items: center; gap: 9px; color: var(--ink); font-size: 18px; font-weight: 500; letter-spacing: -.3px; }\n.own-resend .rs-brand svg { width: 20px; height: 20px; }\n.own-resend .rs-menu { display: flex; align-items: center; gap: 22px; margin: 0 auto; }\n.own-resend .rs-menu a { font-family: var(--sans); font-size: 14px; font-weight: 500; letter-spacing: .35px; color: var(--body); }\n.own-resend .rs-menu a:hover { color: var(--ink); }\n.own-resend .rs-nav-right { display: flex; align-items: center; gap: 14px; margin-left: auto; }\n.own-resend .rs-link { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-resend .rs-link:hover { color: var(--ink); }\n.own-resend .rs-burger { display: none; flex-direction: column; gap: 4px; width: 36px; height: 36px; align-items: center; justify-content: center; border: 1px solid var(--hairline-strong); border-radius: var(--r-md); background: var(--surface-elevated); }\n.own-resend .rs-burger span { display: block; width: 15px; height: 1.6px; background: var(--ink); border-radius: 2px; }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-resend .rs-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 36px; padding: 0 16px; border: 1px solid transparent; border-radius: var(--r-md); font-size: 14px; font-weight: 500; line-height: 1.43; transition: background-color .2s, border-color .2s; }\n.own-resend .rs-btn-primary { background: var(--primary); color: var(--primary-on); }\n.own-resend .rs-btn-primary:hover { background: #f1f7fe; }\n.own-resend .rs-btn-outline { background: var(--canvas); color: var(--ink); border-color: var(--hairline-strong); }\n.own-resend .rs-btn-outline:hover { border-color: var(--ink); }\n.own-resend .rs-btn-ghost { background: var(--surface-elevated); color: var(--ink); border-color: var(--hairline-strong); }\n.own-resend .rs-btn-ghost:hover { background: var(--surface-card); }\n.own-resend .rs-btn-lg { height: 44px; padding: 0 22px; font-size: 15px; }\n.own-resend .rs-btn-block { width: 100%; }\n\n/* ── hero stripe ───────────────────────────────────────────────────────────── */\n.own-resend .rs-hero { position: relative; overflow: hidden; padding: 112px var(--gut) 96px; }\n.own-resend .rs-hero-inner { position: relative; max-width: 900px; margin: 0 auto; text-align: center; }\n.own-resend .rs-badge { display: inline-block; margin-bottom: 22px; padding: 4px 12px; border: 1px solid var(--hairline-strong); border-radius: var(--r-full); background: var(--surface-elevated); color: var(--body); font-size: 12px; }\n.own-resend .rs-h1 { font-family: var(--serif); font-size: clamp(52px, 8.4cqi, 96px); font-weight: 400; line-height: 1; letter-spacing: -.96px; color: var(--ink); font-feature-settings: \"ss01\", \"ss04\", \"ss11\"; }\n.own-resend .rs-hero-sub { max-width: 56ch; margin: 22px auto 0; font-family: var(--sans); font-size: 20px; line-height: 1.3; color: var(--body); }\n.own-resend .rs-hero-cta { display: flex; justify-content: center; gap: 12px; margin-top: 32px; flex-wrap: wrap; }\n\n/* ── section shell ─────────────────────────────────────────────────────────── */\n.own-resend .rs-section { position: relative; overflow: hidden; padding: var(--section) var(--gut) 0; }\n.own-resend .rs-section-tight { padding-top: var(--section); }\n.own-resend .rs-sec-inner { position: relative; max-width: 1200px; margin: 0 auto; }\n.own-resend .rs-h2 { font-family: var(--serif); font-size: clamp(38px, 5.6cqi, 76.8px); font-weight: 400; line-height: 1; letter-spacing: -.768px; color: var(--ink); font-feature-settings: \"ss01\", \"ss04\", \"ss11\"; }\n.own-resend .rs-h2-tight { font-size: clamp(32px, 4.4cqi, 56px); letter-spacing: -1px; }\n.own-resend .rs-sec-sub { margin-top: 16px; max-width: 60ch; font-family: var(--sans); font-size: 17px; line-height: 1.5; color: var(--body); }\n.own-resend .rs-h3 { font-family: var(--ui); font-size: 24px; font-weight: 500; line-height: 1.5; letter-spacing: -.4px; color: var(--ink); }\n.own-resend .rs-eyebrow { font-family: var(--sans); font-size: 14px; font-weight: 500; letter-spacing: .35px; color: var(--accent-blue); margin-bottom: 16px; }\n\n/* ── atmospheric glows ──────────────────────────────────────────────────────── */\n.own-resend .rs-glow { position: absolute; left: 50%; transform: translateX(-50%); pointer-events: none; width: 900px; height: 420px; max-width: 120%; }\n.own-resend .rs-glow-top { top: -120px; }\n.own-resend .rs-glow-orange { top: -60px; background: radial-gradient(50% 60% at 50% 30%, var(--accent-orange-glow), transparent 70%); }\n.own-resend .rs-glow-blue { background: radial-gradient(50% 60% at 50% 30%, var(--accent-blue-glow), transparent 70%); }\n.own-resend .rs-glow-green { background: radial-gradient(50% 60% at 50% 30%, var(--accent-green-glow), transparent 70%); }\n.own-resend .rs-glow-red { background: radial-gradient(50% 60% at 50% 30%, var(--accent-red-glow), transparent 70%); }\n\n/* ── feature grid ──────────────────────────────────────────────────────────── */\n.own-resend .rs-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 40px; }\n.own-resend .rs-card { display: grid; gap: 10px; padding: 32px; border-radius: var(--r-lg); background: var(--surface-card); }\n.own-resend .rs-card-bordered { border: 1px solid var(--hairline-strong); }\n.own-resend .rs-card-icon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: var(--r-md); background: var(--surface-elevated); border: 1px solid var(--hairline); color: var(--accent-blue); }\n.own-resend .rs-card-icon svg { width: 22px; height: 22px; }\n.own-resend .rs-card-copy { font-size: 15px; line-height: 1.5; color: var(--body); }\n\n/* ── split + code window ────────────────────────────────────────────────────── */\n.own-resend .rs-split { display: grid; grid-template-columns: 1fr 1.1fr; gap: 48px; align-items: start; }\n.own-resend .rs-bullets { list-style: none; display: grid; gap: 12px; margin-top: 24px; }\n.own-resend .rs-bullets li { position: relative; padding-left: 26px; font-family: var(--sans); font-size: 16px; letter-spacing: -.8px; color: var(--body); }\n.own-resend .rs-bullets li::before { content: ''; position: absolute; left: 0; top: 8px; width: 8px; height: 8px; border-radius: 50%; background: var(--accent-green); }\n.own-resend .rs-code { border: 1px solid var(--hairline-strong); border-radius: var(--r-lg); background: var(--surface-deep); overflow: hidden; }\n.own-resend .rs-code-top { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-bottom: 1px solid var(--hairline); }\n.own-resend .rs-lights { display: inline-flex; gap: 7px; }\n.own-resend .rs-lights i { width: 11px; height: 11px; border-radius: 50%; }\n.own-resend .rs-l-red { background: var(--accent-red); }\n.own-resend .rs-l-yellow { background: var(--accent-yellow); }\n.own-resend .rs-l-green { background: var(--accent-green); }\n.own-resend .rs-code-name { font-family: var(--mono); font-size: 13px; color: var(--charcoal); }\n.own-resend .rs-code-tabs { display: flex; gap: 4px; padding: 10px 12px 0; }\n.own-resend .rs-tab { padding: 6px 12px; border-radius: var(--r-sm); background: var(--surface-card); color: var(--charcoal); font-family: var(--mono); font-size: 13px; }\n.own-resend .rs-tab.on { color: var(--ink); box-shadow: inset 0 -2px 0 var(--hairline-strong); }\n.own-resend .rs-code-body { margin: 0; padding: 20px 24px 24px; font-family: var(--mono); font-size: 13px; line-height: 1.6; color: var(--body); overflow-x: auto; }\n.own-resend .rs-c-kw { color: #ff9d7a; }\n.own-resend .rs-c-fn { color: var(--accent-blue); }\n.own-resend .rs-c-str { color: var(--accent-green); }\n.own-resend .rs-c-com { color: var(--stone); }\n\n/* ── email mockup inset ─────────────────────────────────────────────────────── */\n.own-resend .rs-email { position: relative; padding: var(--section) var(--gut) 0; }\n.own-resend .rs-mail { position: relative; max-width: 640px; margin: 40px auto 0; border-radius: var(--r-lg); background: #ffffff; color: var(--on-light); overflow: hidden; box-shadow: 0 40px 90px -50px rgba(0, 0, 0, .9); }\n.own-resend .rs-mail-head { display: flex; align-items: center; gap: 12px; padding: 18px 22px; border-bottom: 1px solid rgba(0, 0, 51, .08); }\n.own-resend .rs-mail-dot { width: 34px; height: 34px; border-radius: var(--r-md); background: linear-gradient(135deg, var(--accent-blue), var(--accent-green)); }\n.own-resend .rs-mail-sub { font-family: var(--ui); font-size: 15px; font-weight: 600; color: var(--on-light); }\n.own-resend .rs-mail-to { font-size: 13px; color: var(--on-light-mute); }\n.own-resend .rs-mail-body { padding: 22px; }\n.own-resend .rs-mail-hi { font-family: var(--sans); font-size: 16px; color: var(--on-light); }\n.own-resend .rs-mail-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 18px 0; }\n.own-resend .rs-mail-stats div { display: grid; gap: 2px; padding: 14px; border-radius: var(--r-md); background: #f1f7fe; }\n.own-resend .rs-mail-stats b { font-family: var(--ui); font-size: 24px; font-weight: 600; color: var(--on-light); }\n.own-resend .rs-mail-stats span { font-size: 12px; color: var(--on-light-mute); }\n.own-resend .rs-mail-note { font-size: 13px; color: var(--on-light-mute); border-top: 1px solid rgba(0, 0, 51, .08); padding-top: 14px; }\n\n/* ── pricing ────────────────────────────────────────────────────────────────── */\n.own-resend .rs-price-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 40px; align-items: start; }\n.own-resend .rs-tier { display: grid; gap: 12px; padding: 32px; border: 1px solid var(--hairline-strong); border-radius: var(--r-lg); background: var(--surface-card); }\n.own-resend .rs-tier-featured { background: var(--surface-elevated); }\n.own-resend .rs-tier-name { font-family: var(--ui); font-size: 24px; font-weight: 500; line-height: 1.5; letter-spacing: -.4px; color: var(--ink); }\n.own-resend .rs-tier-price { font-family: var(--sans); font-size: 56px; font-weight: 400; line-height: 1.2; letter-spacing: -2.8px; color: var(--ink); }\n.own-resend .rs-tier-price span { font-family: var(--ui); font-size: 16px; letter-spacing: 0; color: var(--charcoal); }\n.own-resend .rs-tier-desc { font-family: var(--sans); font-size: 16px; letter-spacing: -.8px; color: var(--body); }\n.own-resend .rs-checks { list-style: none; display: grid; gap: 10px; margin: 4px 0; font-family: var(--ui); font-size: 14px; color: var(--body); }\n.own-resend .rs-checks li { padding-left: 24px; position: relative; }\n.own-resend .rs-checks li::before { content: '\\2713'; position: absolute; left: 0; color: var(--accent-green); }\n\n/* ── quote ──────────────────────────────────────────────────────────────────── */\n.own-resend .rs-quote { max-width: 760px; margin: 40px auto 0; text-align: center; }\n.own-resend .rs-quote p { font-family: var(--serif); font-size: clamp(24px, 3cqi, 34px); font-weight: 400; line-height: 1.3; letter-spacing: -.5px; color: var(--ink); }\n.own-resend .rs-quote-by { display: inline-flex; align-items: center; gap: 12px; margin-top: 24px; text-align: left; }\n.own-resend .rs-avatar { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--r-full); background: var(--surface-elevated); border: 1px solid var(--hairline-strong); color: var(--body); font-size: 12px; }\n.own-resend .rs-quote-by b { display: block; font-family: var(--ui); font-size: 14px; font-weight: 500; color: var(--ink); }\n.own-resend .rs-quote-by em { font-style: normal; font-size: 13px; color: var(--mute); }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-resend .rs-foot { margin-top: var(--section); padding: 64px var(--gut) 28px; border-top: 1px solid var(--hairline); }\n.own-resend .rs-foot-inner { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 32px; max-width: 1200px; margin: 0 auto; }\n.own-resend .rs-foot-brand > span { font-family: var(--serif); font-size: 22px; letter-spacing: -.4px; color: var(--ink); }\n.own-resend .rs-foot-status { display: inline-flex; align-items: center; gap: 7px; margin-top: 12px; font-family: var(--ui); font-size: 13px; color: var(--ash); }\n.own-resend .rs-foot-status i { width: 8px; height: 8px; border-radius: 50%; background: var(--accent-green); }\n.own-resend .rs-foot-cols { display: grid; gap: 10px; align-content: start; }\n.own-resend .rs-foot-cols h3 { font-family: var(--ui); font-size: 14px; font-weight: 500; color: var(--ink); margin-bottom: 4px; }\n.own-resend .rs-foot-cols a { font-family: var(--ui); font-size: 14px; color: var(--charcoal); }\n.own-resend .rs-foot-cols a:hover { color: var(--ink); }\n.own-resend .rs-foot-bottom { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1200px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--divider-soft); font-size: 12px; color: var(--ash); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-resend .rs-menu { display: none; }\n  .own-resend .rs-burger { display: flex; }\n  .own-resend .rs-grid { grid-template-columns: 1fr 1fr; }\n  .own-resend .rs-split { grid-template-columns: 1fr; }\n  .own-resend .rs-price-grid { grid-template-columns: 1fr; max-width: 520px; }\n}\n@container frame (max-width: 760px) {\n  .own-resend .rs-link { display: none; }\n  .own-resend .rs-hero { padding: 72px var(--gut) 64px; }\n  .own-resend .rs-h1 { font-size: clamp(44px, 13cqi, 64px); letter-spacing: -.5px; }\n  .own-resend .rs-h2 { font-size: clamp(32px, 9cqi, 44px); }\n  .own-resend .rs-grid { grid-template-columns: 1fr; }\n  .own-resend .rs-mail-stats { grid-template-columns: 1fr; }\n  .own-resend .rs-foot-inner { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-resend .rs-h1 { font-size: 44px; }\n  .own-resend .rs-hero-sub { font-size: 18px; }\n  .own-resend .rs-foot-inner { grid-template-columns: 1fr; }\n  .own-resend .rs-code-body { font-size: 11px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-resend *, .own-resend *::before, .own-resend *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Resend-language chrome for showcase.html ═══════════════════
   Registers window.OWN_LAYOUTS['resend'].init(root). Wires the code tabs;
   returns a cleanup that aborts every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['resend'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }

      on(root, 'click', function (e) {
        var t = e.target.closest ? e.target.closest('.rs-tab') : null;
        if (!t) return;
        Array.prototype.forEach.call(root.querySelectorAll('.rs-tab'), function (x) { x.classList.remove('on'); });
        t.classList.add('on');
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
